import{Port}from'../../core/index.js';import{THREE,box,solid,hole,plastic,metal,frame,portQuaternion,capsule}from'./geometry.js';import{spec}from'./dimensions.js';
function port(host,id,connector,at,face,w,h,pins=[]){return host.add(new Port({id,label:`UnitV2 ${id} · mechanical connector`,connector,position:at,quaternion:portQuaternion(face),hitSize:[w,1,h],pins,meta:{role:'visual-connector',face,scope:'Physical mating and attachment only;no power,USB,UART,filesystem,AI,network or firmware simulation.'}}));}
export function usb(host){const g=frame(host.body,'UnitV2 actual bottom USB-C socket',spec.usb.position,'bottom'),s=capsule(8.6,2.8);s.holes.push(capsule(8,2.2,{path:new THREE.Path(),clockwise:true}));const shield=solid(g,s,5.8,[0,0,-5.8],metal(),'UnitV2 USB-C real annular shield'),stop=box(g,[7.95,2.15,.55],[0,0,-5.6],plastic(),'UnitV2 USB-C rear dielectric'),tongue=box(g,[6.15,.6,3.8],[0,0,-3.0],plastic(),'UnitV2 USB-C dielectric tongue'),contacts=[];for(const sign of[-1,1])for(let i=0;i<12;i++)contacts.push(box(g,[.19,.055,2.1],[(i-5.5)*.5,sign*.33,-2.7],metal(0xc5ab70),'UnitV2 USB-C physical contact appearance'));return{group:g,shield,stop,tongue,contacts,port:port(host,'usb','usb-c',spec.usb.position,'bottom',8.7,2.9)};}
export function grove(host){const g=frame(host.body,'UnitV2 actual white HY2.0-4P bottom socket',spec.grove.position,'bottom'),m=plastic(spec.grove.color),contacts=[],parts=[];for(const x of[-4.65,4.65])parts.push(box(g,[.7,5.1,6.4],[x,0,-3.2],m,'UnitV2 Grove side wall'));parts.push(box(g,[8.6,.65,6.4],[0,-2.23,-3.2],m,'UnitV2 Grove floor'),box(g,[8.6,4.45,.65],[0,.33,-6.08],m,'UnitV2 Grove deep backstop'),box(g,[4.8,.5,2.6],[0,2.3,-4.7],m,'UnitV2 Grove locking bridge'));for(const x of[-3.8,3.8])parts.push(box(g,[.65,.55,1.3],[x,2.3,-1.8],m,'UnitV2 Grove locking shoulder'));for(let i=0;i<4;i++){const x=(i-1.5)*2;contacts.push(box(g,[.42,.42,4.6],[x,.15,-3.6],metal(0xbca976),'UnitV2 Grove contact '+(i+1)));box(g,[.42,1.6,.42],[x,-2.8,-5.6],metal(),'UnitV2 Grove solder tail');}return{group:g,parts,contacts,port:port(host,'grove','grove',spec.grove.position,'bottom',10,5.1,['GND','5V','RX','TX'].map((name,i)=>({n:i+1,name,color:['black','red','yellow','white'][i]})))};}
export function sd(host){const g=frame(host.body,'UnitV2 side microSD real metal cage',spec.sd.position,'left'),m=metal(),s=new THREE.Shape();s.moveTo(-6.5,-.62);s.lineTo(6.5,-.62);s.lineTo(6.5,.62);s.lineTo(-6.5,.62);s.closePath();const opening=new THREE.Path();opening.moveTo(-5.9,-.52);opening.lineTo(-5.9,.52);opening.lineTo(5.9,.52);opening.lineTo(5.9,-.52);opening.closePath();s.holes.push(opening);const walls=solid(g,s,13.4,[0,0,-13.4],m,'UnitV2 microSD genuinely hollow metal cage'),stop=box(g,[11.8,1.04,.45],[0,0,-13.18],plastic(),'UnitV2 microSD deep insertion stop'),floor=box(g,[11.8,.12,12.8],[0,-.58,-6.8],plastic(),'UnitV2 microSD insulating floor'),contacts=[];for(let i=0;i<8;i++)contacts.push(box(g,[.52,.09,3.2],[(i-3.5)*1.1,-.46,-10.6],metal(0xc7ae6d),'UnitV2 microSD eight real spring contacts'));const roof=box(g,[11.7,.08,8.2],[0,.58,-8.5],m,'UnitV2 microSD rear shield roof');return{group:g,walls,stop,floor,roof,contacts,port:port(host,'sd','microsd',spec.sd.position,'left',12,1.1)};}
